TYPES={"table":[["Symbology","Characters","Length","Typical use"],["Code 128","All 128 ASCII characters","Variable","Shipping labels, logistics, GS1-128"],["EAN-13","Digits","13 (12 + check digit)","Retail products worldwide"],["EAN-8","Digits","8 (7 + check digit)","Small retail packages"],["UPC-A","Digits","12 (11 + check digit)","Retail products in the US and Canada"],["Code 39","A–Z, 0–9, space and - . $ / + %","Variable","Industry, defence, ID badges, asset tags"],["ITF-14","Digits","14","Outer cartons and cases"],["Codabar","0–9 and - $ : / . + with A–D start/stop","Variable","Libraries, blood banks, couriers"],["MSI","Digits","Variable","Warehouse shelf labels"],["Pharmacode","Number 3–131070","—","Pharmaceutical packaging control"]]}
def common():
  return [
  ["Download PNG or vector SVG","Every barcode can be saved as a PNG image and as an SVG vector file. PNG is right for Word, Google Docs, label software and web pages; choose 2× or 3× resolution for print so the bars stay crisp. SVG scales to any size without blurring, which is what printers, packaging designers and tools like Illustrator, Inkscape, Affinity and Canva prefer. The SVG contains real rectangles, not an embedded picture."],
  ["Bulk barcode generation","Paste a list of values – one per line – into the *Bulk* box and the tool generates every barcode at once and downloads a ZIP with a numbered PNG and SVG for each value. Invalid entries (for example a wrong EAN check digit) are skipped and listed, so you can fix them. This is ideal for product catalogues, inventory labels, library cards and event tickets exported from a spreadsheet: copy the column from Excel or Google Sheets and paste."],
  ["Printing barcodes that scan first time",{"list":["Keep the quiet zone – the white margin either side of the bars. The generator adds one automatically; do not crop it.","Print dark bars on a light background. Black on white is safest; red bars are invisible to many laser scanners.","Do not shrink retail barcodes much below their nominal size (about 37 × 26 mm for EAN-13).","Use 300 dpi or more, or the SVG file, for labels and packaging.","Test with a phone scanner such as our [QR & barcode scanner](/qr-code-scanner/) before printing a large run."]}],
  ["Barcode types compared",TYPES],
  ["Free barcode vs registered GS1 number","Anyone can draw a barcode, but the *number* inside a retail barcode (EAN or UPC) must be unique worldwide. For products sold through shops and marketplaces such as Amazon you normally need a company prefix licensed from GS1, the not-for-profit organisation that manages these numbers. For internal use – stock rooms, assets, libraries, tickets – you can use any numbering scheme and a symbology like Code 128 or Code 39. This tool creates the image; it does not issue or register numbers."],
  ["Privacy",PRIV]]
def faqc(name):
  return [Q("Is this barcode generator free?","Yes – free, unlimited, no sign-up and no watermark, for personal and commercial use."),
  Q("Can I download the barcode as SVG?","Yes. Every barcode is available as PNG and as a vector SVG for print."),
  Q("Can I make many barcodes at once?","Yes. Paste one value per line in the Bulk box and download a ZIP of PNG and SVG files."),
  Q("What size should I print a barcode?","Print retail codes near their nominal size, keep the white margins and use 300 dpi or the SVG file."),
  Q("Do I need to register the barcode number?","For retail EAN/UPC codes on products sold in shops, yes – get a company prefix from GS1. Internal codes need no registration."),
  Q("Is my data uploaded?","No. The barcode is created in your browser and nothing is sent to a server.")]
