E(S,"barcode",title="Barcode Generator Free – Code 128, EAN-13, UPC, SVG",
 desc="Create barcodes free: Code 128, EAN-13, EAN-8, UPC-A, Code 39, ITF-14, Codabar, MSI. Bulk ZIP, PNG or vector SVG, colours. No upload.",
 compareTitle="{tool}: {brand} vs TEC-IT, Free Barcode Generator and Cognex",compareCols=CC,
 sections=[["Free online barcode generator","Make a scannable barcode in seconds: choose the symbology, type the value and download a PNG or vector SVG. Code 128, EAN-13, EAN-8, UPC-A, Code 39, ITF-14, Codabar, MSI and Pharmacode are supported, with adjustable bar width, height, colours, text size and print resolution, plus bulk generation from a list. No account, no watermark, and nothing is uploaded."],
 ["How to create a barcode",{"steps":["Choose the barcode type – Code 128 if you are unsure.","Type the value; the preview updates as you type and warns when the value is invalid for the chosen type.","Adjust bar width, height, colours, text size and PNG resolution.","Download the PNG, or the SVG for print – or paste a list in Bulk to get a ZIP."]}],
 ["Which barcode type should I use?",{"list":["Selling a product in shops or online marketplaces: EAN-13 (worldwide) or UPC-A (USA/Canada) with a GS1 number – see [EAN-13](/ean-13-barcode-generator/) and [UPC](/upc-barcode-generator/).","Shipping, warehouse and internal labels with letters and numbers: Code 128 – compact and supports every ASCII character.","Asset tags and ID badges read by older scanners: [Code 39](/code-39-barcode-generator/).","Outer cartons: ITF-14.","Need to store a web address, Wi-Fi password or contact card? Use a [QR code](/qr-code-generator/) instead – it holds far more data."]}],
 ["Code 128 in detail","Code 128 encodes all 128 ASCII characters and automatically switches between its three code sets (A, B and C) to keep the barcode short – pure digit runs are packed two per bar pattern. It includes a mandatory modulo-103 check character, so mis-reads are rare. Because it is compact and flexible it is the most common symbology on shipping labels, and the GS1-128 standard used in logistics is built on it."]]+common(),
 compare=CB_,faq=[Q("What is the best free barcode generator?","One that outputs vector SVG, supports the type you need and does not watermark. This one is free, works offline and adds bulk generation."),
  Q("Which barcode type should I choose?","Code 128 for general labels, EAN-13 or UPC-A for retail products, Code 39 for asset tags and older scanners, ITF-14 for cartons."),
  Q("Can I make a barcode in Excel?","Excel has no built-in barcode feature without special fonts. Generate the images here (paste the column into Bulk) and insert them.")]+faqc("barcode")+[Q("Why does my barcode say invalid?","The value does not fit the chosen type – for example letters in EAN-13 or a wrong check digit. Change the value or pick Code 128.")],
 related=rel("barcode-generator"))
